-- UNN Faculty of Engineering: NUC CCMAS 2023 common engineering core (GET courses)
-- =============================================================================
-- Source: Core Curriculum and Minimum Academic Standards (CCMAS) 2023, Engineering and
-- Technology (National Universities Commission; open-access, CC BY-SA 3.0 IGO).
-- The same GET courses appear in every engineering programme in that document. For each
-- one the most common wording across programmes is used as the course description.
--
-- WHAT THIS DOES (additive only, nothing is removed or renamed)
--   1. GET 101 (Engineer in Society) and GET 102 (Engineering Graphics and Solid Modelling I):
--      the common 100 Level courses. Added to every Faculty of Engineering department that
--      does not already have them (a department that still has the old EGR code is left alone).
--   2. Real descriptions and topics are filled into any existing GET row that is still blank.
--   3. Other GET courses (200 to 500 Level) are NOT added to departments, because each UNN
--      department follows its own timetable. Only blank descriptions of rows that already
--      exist are filled.
-- Semester rule from the CCMAS code scheme: an odd last digit is first semester, even is second.
-- =============================================================================
create temp table ccmas_get (course_code text, course_title text, level text, semester text,
  credit_units int, description text, topics jsonb);
insert into ccmas_get values
  ('GET 101', 'Engineer in Society', '100 Level', 'first', 1, 'History, evolution and philosophy of science. engineering and technology. The engineering profession – engineering family (engineers, technologists, technicians and craftsmen), professional bodies and societies. Engineers'' code of conduct and ethics, and engineering literacy. Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics, business. Safety and risk analysis in engineering practice. Engineering competency skills – curriculum overview, technical, soft and digital skills. Guest seminars and invited lectures from different engineering professional associations.', '["History, evolution and philosophy of science","engineering and technology","The engineering profession – engineering family (engineers, technologists, technicians and craftsmen),...","Engineers'' code of conduct and ethics, and engineering literacy","Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics,...","Safety and risk analysis in engineering practice","Engineering competency skills – curriculum overview, technical, soft and digital skills","Guest seminars and invited lectures from different engineering professional associations"]'::jsonb),
  ('GET 102', 'Engineering Graphics and Solid Modelling I', '100 Level', 'second', 2, 'Introduction to design thinking and engineering graphics. First and third angle orthogonal projections. Isometric projections; sectioning, conventional practices, conic sections and development. Freehand and guided sketching – pictorial and orthographic. Visualisation and solid modelling in design, prototyping and product-making. User interfaces in concrete terms. Design, drawing, animation, rendering and simulation workspaces. Sketching of 3D objects. Viewports and sectioning to shop drawings in orthographic projections and perspectives. Automated viewports. Sheet metal and surface modelling. Material selection and rendering. This course will use latest professional design tools such as fusion 360, solid works, solid edge or equivalent.', '["Introduction to design thinking and engineering graphics","First and third angle orthogonal projections","Isometric projections","sectioning, conventional practices, conic sections and development","Freehand and guided sketching – pictorial and orthographic","Visualisation and solid modelling in design, prototyping and product-making","User interfaces in concrete terms","Design, drawing, animation, rendering and simulation workspaces"]'::jsonb),
  ('GET 202', 'Engineering Materials', '200 Level', 'second', 3, 'Basic material science; atomic structure, atomic bonding and crystal structures. Engineering materials situating metals and alloys; metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous) and aluminium (nonferrous) as examples, phase diagrams/iron carbon diagrams, and mechanical workings of metals. Selection and applications of metals and alloys for specific applications in oil, aerospace, construction, manufacturing and transportation industries, among others. Ceramics (including glass); definition, properties, structure and classifications of ceramics. Bioactive and glass – ceramics. Toughing mechanism for ceramics. Polymers; definition of polymers as engineering materials, chemistry of polymeric materials, polymer crystallisation, polymer degradation and aging. Thermoplastic and thermosetting polymers and concepts of copolymers and homopolymers. Composites; definition, classification, characterisation, properties and composite. Applications of composites. Nanomaterials; definition, classification and applications of nanomaterials as emerging technology. Processing of nanomaterials including mechanical grinding, wet chemical synthesis, gas phase synthesis, sputtered plasma processing, microwave plasma processing and laser ablation. Integrity assessment of engineering materials; effect of engineering design, engineering materials processing, selection, manufacturing and assembling on the performance and service life of engineering materials. Metallography and fractography of materials. Mechanical testing (destructive testing) of materials such as compressive test, tensile test, hardness test, impact test, endurance limit and fatigue test. Non-destructive test (NDT) such as dye penetrant, x-ray and eddy current.', '["Basic material science","atomic structure, atomic bonding and crystal structures","Engineering materials situating metals and alloys","metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous)...","Selection and applications of metals and alloys for specific applications in oil, aerospace, construction,...","Ceramics (including glass)","definition, properties, structure and classifications of ceramics","Bioactive and glass – ceramics"]'::jsonb),
  ('GET 204', 'Students Workshop Practice', '200 Level', 'second', 2, 'The course comprises general, mechanical and electrical components: supervised hands-on experience in safe usage of tools and machines for selected tasks; Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and pattern making). Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning. Hand tools, gas and arc welding, cutting, brazing and soldering. Foundry practice.Industrial safety and accident prevention, ergonomics, metrology. Casting processes. Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.). Metal joining processes(welding, brazing and soldering). Heat treatment. Material removal processes. machine tools and classification. Simple theory of metal cutting. Tool action and cutting forces. Introduction to CNC machines. Supervised identification, use and care of various electrical and electronic components such as resistors, inductors, capacitors, diodes and transistors. Exposure to different electric circuits, wiring schemes, analogue and digital electrical and electronic measurements. Household and industrial energy consumption measurements. Practical energy conservation principles.', '["The course comprises general, mechanical and electrical components: supervised hands-on experience in safe...","Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and...","Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning","Hand tools, gas and arc welding, cutting, brazing and soldering","Foundry practice.Industrial safety and accident prevention, ergonomics, metrology","Casting processes","Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.)","Metal joining processes(welding, brazing and soldering)"]'::jsonb),
  ('GET 205', 'Fundamentals of Fluid Mechanics', '200 Level', 'first', 3, 'Fluid properties, hydrostatics, fluid dynamics using principles of mass, momentum and energy conservation from a control volume approach. Flow measurements in pipes, dimensional analysis, and similitude, 2-dimensional flows. Hydropower systems.', '["Fluid properties, hydrostatics, fluid dynamics using principles of mass, momentum and energy conservation...","Flow measurements in pipes, dimensional analysis, and similitude, 2-dimensional flows","Hydropower systems"]'::jsonb),
  ('GET 206', 'Fundamentals of Engineering Thermodynamics', '200 Level', 'second', 3, 'Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of thermodynamics). Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases); state diagrams. The principle of corresponding state; compressibility relations; reduced pressure; reduced volume; temperature; pseudo-critical constants. The ideal gas: specific heat, polytropic processes. Ideal gas cycles; Carnot; thermodynamic cycles, turbines, steam and gas, refrigeration. The first law of thermodynamics – heat and work, applications to open and closed systems. The steady flow energy equation (Bernoulli’s equation) and application. Second law of thermodynamics, heat cycles and efficiencies.', '["Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of...","Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases)","state diagrams","The principle of corresponding state","compressibility relations","reduced pressure","reduced volume","temperature"]'::jsonb),
  ('GET 209', 'Engineering Mathematics I', '200 Level', 'first', 3, 'Limits, continuity, differentiation, introduction to linear first order differential equations, partial and total derivatives, composite functions, matrices and determinants, vector algebra, vector calculus, directional derivatives.', '["Limits, continuity, differentiation, introduction to linear first order differential equations, partial..."]'::jsonb),
  ('GET 210', 'Engineering Mathematics II', '200 Level', 'second', 3, 'Introduction to ordinary differential equations (ODEs); theory, applications, methods of solution; second order differential equations. Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and their applications). Elementary complex analysis including functions of complex variables, limits and continuity. Derivatives, differentiation rules and differentiation of integrals. Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping and its applications to engineering problems. Special functions.', '["Introduction to ordinary differential equations (ODEs)","theory, applications, methods of solution","second order differential equations","Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and...","Elementary complex analysis including functions of complex variables, limits and continuity","Derivatives, differentiation rules and differentiation of integrals","Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping...","Special functions"]'::jsonb),
  ('GET 211', 'Computing and Software Engineering', '200 Level', 'first', 3, 'Introduction to computers and computing; computer organisation – data processing, memory, registers and addressing schemes; Boolean algebra; floating-point arithmetic; representation of non-numeric information; problem-solving and algorithm development; coding (solution design using flowcharts and pseudo codes). Data models and data structures; computer software and operating system; computer operators and operators precedence; components of computer programs; introduction to object oriented, structured and visual programming; use of MATLAB in engineering applications. ICT fundamentals, Internet of Things (IoT). Elements of software engineering.', '["Introduction to computers and computing","computer organisation – data processing, memory, registers and addressing schemes","Boolean algebra","floating-point arithmetic","representation of non-numeric information","problem-solving and algorithm development","coding (solution design using flowcharts and pseudo codes)","Data models and data structures"]'::jsonb),
  ('GET 302', 'Engineering Mathematics IV', '300 Level', 'second', 3, 'Series solution of second order linear differential equations with variable coefficients. Bessel and Legendre equations. Equations with variable coefficients. Sturm-Liouville boundary value problems. Solutions of equations in two and three dimensions by separation of variables. Eigen value problems. Use of operations in the solution of partial differential equations and Linear integral equations. Integral transforms and their inverse including Fourier, Laplace, Mellin and Handel Transforms. Convolution integrals and Hilbert Transforms. Calculus of finite differences. Interpolation formulae. Finite difference equations. RungeKutta and other methods in the solutions of ODE and PDEs. Numerical integration and differentiation.', '["Series solution of second order linear differential equations with variable coefficients","Bessel and Legendre equations","Equations with variable coefficients","Sturm-Liouville boundary value problems","Solutions of equations in two and three dimensions by separation of variables","Eigen value problems","Use of operations in the solution of partial differential equations and Linear integral equations","Integral transforms and their inverse including Fourier, Laplace, Mellin and Handel Transforms"]'::jsonb),
  ('GET 304', 'Technical Writing and Communication', '300 Level', 'second', 3, 'A brief review of common pitfalls in writing. Principles of clear writing (punctuations and capitalization). Figures of speech. Units of grammar. Tenses and verb agreement. Active and passive sentences Lexis and structure Fog Index concept. Skills for communication and communication algorithm. Types and goals of communication; Interpersonal communication; features and the Finger Model or A,B,C,D,E of good interpersonal communication (accuracy of technical terms, brevity of expression, clarity of purpose, directness of focus and effectiveness of the report). Language and organisation of reports. Technical report writing skills(steps, problems in writing, distinguishing technical and other reports, significance, format and styles of writing technical reports). Different formats for communication; styles of correspondences – business report and proposal, business letter, memorandum, e-mails, etc. Proposals for projects and research; format, major steps and tips of grant-oriented proposals. Research reports(competency, major steps, components and formats of research reports and publishable communication). Sources and handling of data, tables, figures, equations and references in a report. Presentation skills; overview, tips, organisation, use of visual aids and practising of presentation. Intellectual property rights in research reports. Case studies of major engineering designs, proposals and industrial failures with professional presentation of reports.', '["A brief review of common pitfalls in writing","Principles of clear writing (punctuations and capitalization)","Figures of speech","Units of grammar","Tenses and verb agreement","Active and passive sentences Lexis and structure Fog Index concept","Skills for communication and communication algorithm","Types and goals of communication"]'::jsonb),
  ('GET 305', 'Engineering Statistics and Data Analytics', '300 Level', 'first', 3, 'Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data sampling, mean, median, mode, mean deviation, percentiles. Probability. Binomial, Poisson hyper-geometric, normal distributions. Statistical inference intervals, test hypothesis and significance. Regression and correlation. Introduction to big data analytics and cloud computing applications. Introduction to the R language; R as a calculator; Vectors, matrices, factors, data frames and other R collections. Iteration and looping control structures. Conditionals and other controls. Designing, using and extending functions. The Apply Family. Statistical modelling and inference in R. .', '["Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data...","Probability","Binomial, Poisson hyper-geometric, normal distributions","Statistical inference intervals, test hypothesis and significance","Regression and correlation","Introduction to big data analytics and cloud computing applications","Introduction to the R language","R as a calculator"]'::jsonb),
  ('GET 501', 'Engineering Project Management', '500 Level', 'first', 3, 'Project management fundamentals – definitions, project environment, nature and characteristics, development practice, management by objectives, and the centrality of engineering to projects, infrastructures, national and global development. The scope of project management – organisational, financial, planning and control, personnel management, labour and public relations, wages and salary administration and resource management. Identification of project stakeholders; beneficiaries and impacted persons – functions, roles, responsibilities. Project community relations, communication and change management. Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown structure (WBS), deliverables and timelines, logical frameworks (log frames), risk analysis, role of subject matter experts (SMEs), role conflicts; Gantt Chart, CPM and PERT. Optimisation, linear programming as an aid to decision making, transport and materials handling. Monitoring and Evaluation – key performance indices (KPIs); methods of economic and technical evaluation. Industrial psychology, ergonomics/human factors and environmental impact considerations in engineering project design and management. Project business case - financial, technical and sustainability considerations. Case studies, site visits and invited industry professional seminars. General principles of management and appraisal techniques. Breakthrough and control management theory; production and maintenance management. Training and manpower development. The manager and policy formulation, objective setting, planning, organising and controlling, motivation and appraisal of results.', '["Project management fundamentals – definitions, project environment, nature and characteristics,...","The scope of project management – organisational, financial, planning and control, personnel management,...","Identification of project stakeholders","beneficiaries and impacted persons – functions, roles, responsibilities","Project community relations, communication and change management","Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown...","Gantt Chart, CPM and PERT","Optimisation, linear programming as an aid to decision making, transport and materials handling"]'::jsonb),
  ('GET 502', 'Engineering Law', '500 Level', 'second', 2, 'Common Law: its history, definition, nature and division. Legislation, codification interpretation. Equity: definition and its main spheres. Law of contracts for Engineers: Forms of contract and criteria for selecting contractors; offer, acceptance, communication termination of contract. Terms of Contracts; suppliers’ duties – Damages and other Remedies. Termination/cancellation of contract Liquidation and Penalties; exemption clauses, safety and risk. Health and Safety. Duties of employers towards their employees. Duties imposed on employees. Fire precautions act. Design for safety. General principles of criminal law. Law of torts: definition, classification and liabilities. Patents: requirements, application, and infringement. Registered designs: application, requirements, types and infringement. Company law. Labour law and Industrial Law. Business registration.', '["Common Law: its history, definition, nature and division","Legislation, codification interpretation","Equity: definition and its main spheres","Law of contracts for Engineers: Forms of contract and criteria for selecting contractors","offer, acceptance, communication termination of contract","Terms of Contracts","suppliers’ duties – Damages and other Remedies","Termination/cancellation of contract Liquidation and Penalties"]'::jsonb),
  ('GET 201', 'Applied Electricity I', '200 Level', 'first', 3, 'Fundamental concepts: Electric fields, charges, magnetic fields. current, B-H curves Kirchhoff’s laws, superposition. Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits. DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits, Complex j - notation, AC circuits, impedance, admittance, susceptance.', '["Fundamental concepts: Electric fields, charges, magnetic fields","current, B-H curves Kirchhoff’s laws, superposition","Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits","DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits,..."]'::jsonb),
  ('GET 306', 'Renewable Energy Systems and Technology', '300 Level', 'second', 3, 'Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in energy conversion systems; parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting 21st-century national, regional and global energy needs in a sustainable manner. Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal). Energy types, storage, transmission and conservation. Analysis of energy mixes within an engineering, economic and social context. Sustainable energy; emphasise sustainability in general and in the overall concept of sustainable development and the link this has with sustainable energy as the fundamental benefit of renewable energy. Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific value of fuels and biomass; measurement of the velocity of wind, waves and the energy that abound in them; laboratory production of biogas and determination of energy available in it; simple conversion of solar energy to electricity; transesterification of edible oil into biodiesel; simulation of geothermal energy; Geiger-Muller or Scintillation Counters’ determination of uranium or thorium energy; simple solid or salt storage of energy; hybrid application of renewable energy.', '["Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in...","parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting...","Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission...","Energy types, storage, transmission and conservation","Analysis of energy mixes within an engineering, economic and social context","Sustainable energy","emphasise sustainability in general and in the overall concept of sustainable development and the link...","Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific..."]'::jsonb),
  ('GET 208', 'Strength of Materials', '200 Level', 'second', 3, 'Consideration of equilibrium; composite members, stress-strain relation. Generalised Hooke''s law. Stresses and strains due to loading and temperature changes. Torsion of circular members. Shear force, bending moments and bending stresses in beams with symmetrical and combined loadings. Stress and strain transformation equations and Mohr’s circle. Elastic buckling of columns.', '["Consideration of equilibrium","composite members, stress-strain relation","Generalised Hooke''s law","Stresses and strains due to loading and temperature changes","Torsion of circular members","Shear force, bending moments and bending stresses in beams with symmetrical and combined loadings","Stress and strain transformation equations and Mohr’s circle","Elastic buckling of columns"]'::jsonb),
  ('GET 203', 'Engineering Graphics and Solid Modeling II', '200 Level', 'first', 3, 'Projection of lines, auxiliary views and mixed projection. Preparation of detailed working production drawing; semi-detailed drawings, conventional presentation methods. Solid, surface and shell modeling. Faces, bodies and surface intersections. Component-based design. Component assembly and motion constraints. Constrained motions and animation. Introduction to electronics modeling. Electronics board layout preparation, Component libraries and Schematic design. Parametric modeling and adaptive design. Simulation for material optimization. Designing for manufacturing. Additive and subtractive manufacturing. Production for 3-D printing, Laser cutting and CNC machinery.Arrangement of engineering components to form a working plant (Assembly Drawing of a Plant).', '["Projection of lines, auxiliary views and mixed projection","Preparation of detailed working production drawing","semi-detailed drawings, conventional presentation methods","Solid, surface and shell modeling","Faces, bodies and surface intersections","Component-based design","Component assembly and motion constraints","Constrained motions and animation"]'::jsonb),
  ('GET 207', 'Applied Mechanics', '200 Level', 'first', 3, 'Forces, moments, couples. Equilibrium of simple structures and machine parts. Friction. First and second moments of area; centroids. Kinematics of particles and rigid bodies in plane motion. Newton''s laws of motion. Kinetic energy and momentum analyse.', '["Forces, moments, couples","Equilibrium of simple structures and machine parts","First and second moments of area","centroids","Kinematics of particles and rigid bodies in plane motion","Newton''s laws of motion","Kinetic energy and momentum analyse"]'::jsonb);

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name, is_elective)
select g.course_code, g.course_title, 'University of Nigeria, Nsukka', d.faculty, d.department,
       g.level, g.semester, g.credit_units, g.description, g.topics, 'NUC CCMAS 2023 (Engineering)', false
  from ccmas_get g
 cross join (select distinct faculty, department from public.course_outlines
              where institution = 'University of Nigeria, Nsukka'
                and faculty ilike '%Engineering%' and faculty not ilike '%Agric%') d
 where g.course_code in ('GET 101', 'GET 102')
   and not exists (
     select 1 from public.course_outlines c
      where c.institution = 'University of Nigeria, Nsukka'
        and c.department = d.department
        and (c.course_code = g.course_code
             or (g.course_code = 'GET 101' and c.course_code = 'EGR 101')
             or (g.course_code = 'GET 102' and c.course_code = 'EGR 102')));

update public.course_outlines t
   set description = g.description,
       topics = case when t.topics is null or t.topics = '[]'::jsonb then g.topics else t.topics end
  from ccmas_get g
 where t.institution = 'University of Nigeria, Nsukka'
   and t.course_code = g.course_code
   and t.faculty ilike '%Engineering%'
   and coalesce(trim(t.description), '') = '';

select department, count(*) filter (where course_code in ('GET 101','GET 102')) as get_101_102_rows
  from public.course_outlines
 where institution = 'University of Nigeria, Nsukka' and faculty ilike '%Engineering%'
 group by department order by department;
